        address spender,
        uint256 amount
    ) internal virtual {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");

        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }

function batchCancelListings(uint256[] calldata listingIds)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        uint256 canceledCount = 0;
        for (uint256 i = 0; i < listingIds.length; i++) {
            AsteroidXMarketplaceStructs.Listing storage listing = listings[
                listingIds[i]
            ];
            if (listing.seller != msg.sender)
                revert NotSeller(listingIds[i], msg.sender);
            if (listing.active) {
                _deactivateListing(listingIds[i]);
                marketplaceVaultContract.returnNFTToSeller(
                    address(asteroidXToken),
                    listing.tokenId,
                    listing.amount,
                    listing.seller
                );
                _recordTransaction(
                    listing.tokenId,
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING,
                    msg.sender,
                    address(0),
                    listing.amount,
                    0,
                    listing.paymentToken,
                    listingIds[i]
                );
                emit ListingCancelled(listingIds[i]);
                canceledCount++;
            }
        }
        if (canceledCount > 0) {
            emit BatchOperation(
                uint256(
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING
                ),
                canceledCount
            );
        }
    }

