function _recordPriceHistory(
        uint256 relatedId,
        uint256 tokenId,
        uint256 pricePerToken,
        uint256 amount,
        address seller,
        address buyer,
        address paymentToken
    ) internal returns (uint256) {
        uint256 totalValue = pricePerToken * amount;
        AsteroidXMarketplaceStructs.PriceRecord
            memory priceRecord = AsteroidXMarketplaceStructs.PriceRecord({
                listingId: relatedId,
                tokenId: tokenId,
                price: pricePerToken,
                amount: amount,
                totalValue: totalValue,
                timestamp: block.timestamp,
                seller: seller,
                buyer: buyer,
                paymentToken: paymentToken
            });
        uint256 recordIndex = priceHistories.length;
        priceHistories.push(priceRecord);
        tokenPriceHistoryIndexes[tokenId].push(recordIndex);
        emit PriceHistoryRecorded(
            tokenId,
            relatedId,
            pricePerToken,
            amount,
            totalValue,
            block.timestamp,
            seller,
            buyer,
            paymentToken
        );
        return recordIndex;
    }

function _remove(Set storage set, bytes32 value) private returns (bool) {
        // We cache the value's position to prevent multiple reads from the same storage slot
        uint256 position = set._positions[value];

        if (position != 0) {
            // Equivalent to contains(set, value)
            // To delete an element from the _values array in O(1), we swap the element to delete with the last one in
            // the array, and then remove the last element (sometimes called as 'swap and pop').
            // This modifies the order of the array, as noted in {at}.

            uint256 valueIndex = position - 1;
            uint256 lastIndex = set._values.length - 1;

            if (valueIndex != lastIndex) {
                bytes32 lastValue = set._values[lastIndex];

                // Move the lastValue to the index where the value to delete is
                set._values[valueIndex] = lastValue;
                // Update the tracked position of the lastValue (that was just moved)
                set._positions[lastValue] = position;
            }

            // Delete the slot where the moved value was stored
            set._values.pop();

            // Delete the tracked position for the deleted slot
            delete set._positions[value];

            return true;
        } else {
            return false;
        }
    }

function makeOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    )
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        _validateOffer(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        uint256 totalOfferValue = amount * pricePerToken;
        uint256 offerId = _nextOfferId++;
        _handlePayment(
            paymentToken,
            msg.sender,
            address(this),
            totalOfferValue,
            msg.value
        );
        if (paymentToken == address(0)) {
            marketplaceVaultContract.depositOfferFunds{value: totalOfferValue}(
                offerId
            );
        } else {
            IERC20 token = IERC20(paymentToken);
            token.approve(address(marketplaceVaultContract), totalOfferValue);
            marketplaceVaultContract.depositOfferERC20Funds(
                offerId,
                paymentToken,
                totalOfferValue,
                address(this)
            );
        }
        offers[offerId] = AsteroidXMarketplaceStructs.Offer({
            offerId: offerId,
            buyer: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeOffersByToken[tokenId].add(offerId);
        activeOffersByBuyer[msg.sender].add(offerId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.MAKE_OFFER,
            msg.sender,
            address(marketplaceVaultContract),
            amount,
            pricePerToken,
            paymentToken,
            offerId
        );
        emit OfferCreated(
            offerId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

function _validateOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) internal view {
        address fundsWallet = IERC1155AsteroidX(address(asteroidXToken))
            .fundsWallet(tokenId);
        if (fundsWallet == address(0)) {
            revert TokenDoesNotExist(tokenId);
        }
        if (amount == 0 || amount > MAX_AMOUNT_PER_LISTING)
            revert InvalidOfferAmount(amount);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidOfferPrice(pricePerToken);
        if (expirationTime <= block.timestamp)
            revert OfferExpired(0, expirationTime);
        if (!_supportedPaymentTokensSet.contains(paymentToken))
            revert UnsupportedPaymentToken(paymentToken);
    }

function _handlePayment(
        address paymentToken,
        address from,
        address to,
        uint256 amount,
        uint256 msgValue
    ) internal {
        if (paymentToken == address(0)) {
            if (msgValue < amount) revert InsufficientETHSent(msgValue, amount);
            if (amount > 0) {
                (bool success, ) = payable(to).call{value: amount}("");
                if (!success) revert EthTransferFailed(to);
            }
            if (msgValue > amount) {
                uint256 excessToRefund = msgValue - amount;
                (bool refundSuccess, ) = payable(from).call{
                    value: excessToRefund
                }("");
                if (!refundSuccess) revert EthRefundFailed(from);
            }
        } else {
            if (!_supportedPaymentTokensSet.contains(paymentToken))
                revert UnsupportedPaymentToken(paymentToken);
            if (msgValue != 0) revert UnexpectedETHPayment();
            IERC20 token = IERC20(paymentToken);
            if (token.allowance(from, address(this)) < amount)
                revert InsufficientAllowance(
                    amount,
                    token.allowance(from, address(this)),
                    paymentToken
                );
            if (token.balanceOf(from) < amount)
                revert InsufficientBalance(
                    amount,
                    token.balanceOf(from),
                    paymentToken
                );
            token.safeTransferFrom(from, to, amount);
        }
    }

